const FALLBACK_CITIES={"القاهرة":{lat:30.0444,lng:31.2357,country:"مصر"},"الإسكندرية":{lat:31.2001,lng:29.9187,country:"مصر"},"مكة المكرمة":{lat:21.4225,lng:39.8262,country:"السعودية"},"المدينة":{lat:24.5247,lng:39.5692,country:"السعودية"},"الرياض":{lat:24.7136,lng:46.6753,country:"السعودية"},"جدة":{lat:21.4858,lng:39.1925,country:"السعودية"},"دبي":{lat:25.2048,lng:55.2708,country:"الإمارات"},"الكويت":{lat:29.3759,lng:47.9774,country:"الكويت"},"الدوحة":{lat:25.2854,lng:51.531,country:"قطر"},"عمّان":{lat:31.9454,lng:35.9284,country:"الأردن"},"بغداد":{lat:33.3152,lng:44.3661,country:"العراق"},"الخرطوم":{lat:15.5007,lng:32.5599,country:"السودان"},"بيروت":{lat:33.8938,lng:35.5018,country:"لبنان"},"دمشق":{lat:33.5138,lng:36.2765,country:"سوريا"},"تونس":{lat:36.8065,lng:10.1815,country:"تونس"},"الجزائر":{lat:36.7538,lng:3.0588,country:"الجزائر"},"الرباط":{lat:34.0209,lng:-6.8416,country:"المغرب"},"إسطنبول":{lat:41.0082,lng:28.9784,country:"تركيا"}};const SAVED_LOCATION_KEY="zad_saved_location";async function getLocationWithFallback(){const saved=getSavedLocation();if(saved)return saved;try{const pos=await window._getGeoLocation({timeout:6e3});const loc={lat:pos.coords.latitude,lng:pos.coords.longitude,source:"gps"};saveLocation(loc);return loc}catch(gpsErr){console.log("[Location] GPS فشل، نجرّب IP...")}try{const loc=await getLocationByIP();if(loc){saveLocation(loc);return loc}}catch(ipErr){console.log("[Location] IP فشل، نطلب اختيار يدوي")}return null}window.getLocationWithFallback=getLocationWithFallback;function getSavedLocation(){try{const raw=localStorage.getItem(SAVED_LOCATION_KEY);return raw?JSON.parse(raw):null}catch{return null}}function saveLocation(loc){try{localStorage.setItem(SAVED_LOCATION_KEY,JSON.stringify({...loc,ts:Date.now()}))}catch{}}async function getLocationByIP(){try{const res=await fetch("https://ipapi.co/json/",{signal:AbortSignal.timeout(5e3)});const data=await res.json();if(data.latitude&&data.longitude){return{lat:data.latitude,lng:data.longitude,city:data.city,source:"ip"}}}catch{}return null}function showCityPicker(){if(document.getElementById("city-picker-modal"))return;const modal=document.createElement("div");modal.id="city-picker-modal";modal.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px";modal.innerHTML=`\n    <div style="background:var(--card,#fff);border-radius:20px;padding:24px;width:100%;max-width:400px;max-height:80vh;overflow:auto">\n      <h3 style="margin:0 0 8px;font-size:17px">📍 اختر مدينتك</h3>\n      <p style="font-size:13px;color:var(--muted,#888);margin:0 0 16px">لحساب مواقيت الصلاة والقبلة بدقة</p>\n      <input id="city-search" placeholder="ابحث عن مدينتك..." aria-label="ابحث عن مدينتك"\n             style="width:100%;padding:12px;border-radius:10px;border:1.5px solid var(--border,#ddd);background:var(--sand,#faf9f6);font-family:inherit;margin-bottom:12px;box-sizing:border-box"\n             oninput="filterCities(this.value)">\n      <div id="city-list">\n        ${Object.entries(FALLBACK_CITIES).map(([name,c])=>`\n          <div class="city-option" data-city="${name}" onclick="selectCity('${name}')"\n               style="padding:12px 14px;border-radius:10px;cursor:pointer;display:flex;justify-content:space-between;border-bottom:1px solid var(--border,#eee)">\n            <span style="font-weight:600">${name}</span>\n            <span style="font-size:12px;color:var(--muted,#888)">${c.country}</span>\n          </div>\n        `).join("")}\n      </div>\n    </div>`;document.body.appendChild(modal)}window.showCityPicker=showCityPicker;function filterCities(q){document.querySelectorAll(".city-option").forEach(el=>{const name=el.dataset.city;el.style.display=name.includes(q.trim())?"flex":"none"})}window.filterCities=filterCities;function selectCity(name){const c=FALLBACK_CITIES[name];if(!c)return;saveLocation({lat:c.lat,lng:c.lng,city:name,source:"manual"});document.getElementById("city-picker-modal")?.remove();if(typeof showToast==="function")showToast(`📍 تم اختيار ${name}`);if(typeof renderPrayerTimesPage==="function")renderPrayerTimesPage();setTimeout(()=>location.reload(),600)}window.selectCity=selectCity;let _serverTimeOffset=0;async function syncServerTime(){try{const before=Date.now();const res=await fetch("https://api.aladhan.com/v1/currentTime?zone=UTC",{signal:AbortSignal.timeout(5e3),cache:"no-store"});const after=Date.now();const networkDelay=(after-before)/2;let serverMs=NaN;const dateHeader=res.headers.get("date");if(dateHeader){const t=new Date(dateHeader).getTime();if(!isNaN(t))serverMs=t+networkDelay}if(isNaN(serverMs)){const data=await res.json().catch(()=>null);const raw=data?.data;if(typeof raw==="string"&&/^\d{1,2}:\d{2}/.test(raw)){const[h,m]=raw.split(":").map(Number);const now=new Date;const utc=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate(),h,m,0);if(!isNaN(utc))serverMs=utc+networkDelay}else if(raw){const t=new Date(raw).getTime();if(!isNaN(t))serverMs=t+networkDelay}}if(isNaN(serverMs)){_serverTimeOffset=0;console.log("[Time] تعذّر تحديد فارق السيرفر — استخدام توقيت الجهاز");return}_serverTimeOffset=serverMs-after;console.log(`[Time] الفارق مع السيرفر: ${Math.round(_serverTimeOffset/1e3)} ثانية`)}catch{_serverTimeOffset=0}}function getCorrectedNow(){return new Date(Date.now()+_serverTimeOffset)}window.getCorrectedNow=getCorrectedNow;const AUDIO_STATE_KEY="zad_audio_state";function initPersistentAudio(){document.querySelectorAll("audio").forEach(audio=>{if(audio._zadTracked)return;audio._zadTracked=true;audio.addEventListener("play",()=>{saveAudioState(audio.src,audio.currentTime,true)});audio.addEventListener("pause",()=>{saveAudioState(audio.src,audio.currentTime,false)});audio.addEventListener("timeupdate",()=>{if(!audio.paused){if(!audio._lastSave||Date.now()-audio._lastSave>3e3){saveAudioState(audio.src,audio.currentTime,true);audio._lastSave=Date.now()}}});const state=getAudioState();if(state&&state.src===audio.src&&state.playing){audio.currentTime=state.time||0;showResumeBar(audio,state.time)}})}function saveAudioState(src,time,playing){try{sessionStorage.setItem(AUDIO_STATE_KEY,JSON.stringify({src:src,time:time,playing:playing,ts:Date.now()}))}catch{}}function getAudioState(){try{const raw=sessionStorage.getItem(AUDIO_STATE_KEY);return raw?JSON.parse(raw):null}catch{return null}}function showResumeBar(audio,time){if(document.getElementById("audio-resume-bar"))return;const bar=document.createElement("div");bar.id="audio-resume-bar";bar.style.cssText=`\n    position:fixed;bottom:16px;right:16px;left:16px;z-index:9000;\n    background:var(--zad-green-900,#0e3b2e);color:#fff;padding:12px 16px;\n    border-radius:14px;display:flex;align-items:center;justify-content:space-between;\n    box-shadow:0 8px 24px rgba(0,0,0,.2);font-size:14px;max-width:400px;margin:0 auto;\n  `;const mins=Math.floor(time/60),secs=Math.floor(time%60);bar.innerHTML=`\n    <span>🎵 استئناف من ${mins}:${String(secs).padStart(2,"0")}؟</span>\n    <div style="display:flex;gap:8px">\n      <button onclick="this.closest('#audio-resume-bar').remove()" \n              style="background:none;border:none;color:#fff;opacity:.7;cursor:pointer">لا</button>\n      <button id="resume-yes" style="background:#fff;color:var(--zad-green-900,#0e3b2e);border:none;padding:6px 14px;border-radius:8px;font-weight:700;cursor:pointer">استئناف</button>\n    </div>`;document.body.appendChild(bar);bar.querySelector("#resume-yes").onclick=()=>{audio.currentTime=time;audio.play().catch(()=>{});bar.remove()}}function replaceZeroStates(){const isNewUser=!localStorage.getItem("zad_v2")&&!localStorage.getItem("zad_has_data");if(!isNewUser)return;document.querySelectorAll("#prog-txt, .prog-txt").forEach(el=>{if(el.textContent.includes("0 من")||el.textContent.trim()==="0%"){el.innerHTML='<span style="color:var(--green-mid,#1a5d47)">ابدأ رحلتك — أول عبادة بانتظارك 🌱</span>'}});document.querySelectorAll(".stat-num, #stat-takbeer, #stat-juz").forEach(el=>{if(el.textContent.trim()==="0"||el.textContent.trim()==="٠"){el.style.opacity="0.5"}})}function applyLazyLoading(){document.querySelectorAll("img:not([loading])").forEach(img=>{img.setAttribute("loading","lazy")});document.querySelectorAll('iframe[src*="youtube"]:not([loading])').forEach(iframe=>{iframe.setAttribute("loading","lazy")});document.querySelectorAll("video:not([preload])").forEach(video=>{video.setAttribute("preload","metadata")})}async function shareAchievement(title,subtitle){const canvas=document.createElement("canvas");canvas.width=1080;canvas.height=1080;const ctx=canvas.getContext("2d");const grad=ctx.createLinearGradient(0,0,1080,1080);grad.addColorStop(0,"#0e3b2e");grad.addColorStop(1,"#1a5d47");ctx.fillStyle=grad;ctx.fillRect(0,0,1080,1080);ctx.textAlign="center";ctx.fillStyle="#c9a14a";ctx.font="bold 80px Arial";ctx.fillText("زاد",540,300);ctx.fillStyle="#fff";ctx.font="bold 64px Arial";ctx.fillText(title,540,540);if(subtitle){ctx.fillStyle="rgba(255,255,255,.85)";ctx.font="44px Arial";ctx.fillText(subtitle,540,640)}ctx.fillStyle="rgba(255,255,255,.6)";ctx.font="36px Arial";ctx.fillText("zad.codeandcanvas.net",540,980);canvas.toBlob(async blob=>{const file=new File([blob],"zad-achievement.png",{type:"image/png"});if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:"زاد",text:title});return}catch{}}const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="zad-achievement.png";a.click();URL.revokeObjectURL(url);if(typeof showToast==="function")showToast("✅ تم حفظ الصورة — شاركها مع أحبابك")},"image/png")}window.shareAchievement=shareAchievement;document.addEventListener("DOMContentLoaded",()=>{syncServerTime();initPersistentAudio();replaceZeroStates();applyLazyLoading();if(document.getElementById("prayer-times-container")||document.querySelector("[data-time24]")){getLocationWithFallback().then(loc=>{if(!loc){setTimeout(showCityPicker,1e3)}})}console.log("[ZadFixes] ✅ حزمة الإصلاحات مطبّقة")});